const html = $json.html;
const liste = $('Code - Liste recettes healthy').item.json;

const toMin = d => {
  const m = (d || '').match(/PT(?:(\d+)H)?(?:(\d+)M)?/);
  return m ? (+(m[1] || 0)) * 60 + (+(m[2] || 0)) : null;
};

for (const b of html.matchAll(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/g)) {
  try {
    const data = JSON.parse(b[1]);
    const list = Array.isArray(data) ? data : (data['@graph'] || [data]);
    const r = list.find(x => x['@type'] === 'Recipe');
    if (!r) continue;
    return {
      json: {
        nom: r.name,
        url: liste.url,
        categorie: liste.categorie,
        note: r.aggregateRating?.ratingValue ?? liste.note,
        nb_avis: r.aggregateRating?.reviewCount ?? liste.nb_avis,
        portions: r.recipeYield,
        temps_preparation_min: toMin(r.prepTime),
        temps_cuisson_min: toMin(r.cookTime),
        temps_total_min: toMin(r.totalTime),
        ingredients: r.recipeIngredient || [],
        etapes: (r.recipeInstructions || []).map(s => (s.text || s).trim()),
        image: Array.isArray(r.image) ? r.image[0] : r.image,
      },
    };
  } catch (e) {}
}
return { json: { url: liste.url, erreur: 'Pas de JSON-LD Recipe trouvé' } };

const decode = s => (s || '')
  .replace(/&#0?39;/g, "'").replace(/&quot;/g, '"').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();

const out = [];
const vus = new Set();

// Une entrée = une page de la sélection (page 1, page 2…)
for (const [p, item] of $input.all().entries()) {
  const html = item.json.html || '';
  const cards = html.split('class="search-list__item"').slice(1);

  for (const c of cards) {
    const href = c.match(/href="(\/recettes\/recette_[^"]+)"/)?.[1];
    if (!href) continue;
    const url = 'https://www.marmiton.org' + href;
    if (vus.has(url)) continue; // évite les doublons
    vus.add(url);

    out.push({
      json: {
        position: out.length + 1,
        page: p + 1,
        nom: decode(c.match(/card-content__title[^>]*>\s*([^<]+?)\s*<\/a>/)?.[1]),
        url,
        image: c.match(/<img[^>]+(?:data-src|src)="([^"]+)"/)?.[1] ?? null,
        categorie: decode(c.match(/class="image-label">\s*([^<]+?)\s*</)?.[1]) || null,
        note: parseFloat(c.match(/class="rating__rating">\s*([\d.]+)\/5/)?.[1]) || null,
        nb_avis: parseInt(c.match(/class="rating__nbreviews">\s*(\d+)/)?.[1]) || null,
      },
    });
  }
}
return out;

const regimes = ['detox', 'vegetarien', 'sans-gluten', 'sans-lactose', 'diabetique'];

return regimes.map(r => ({
  json: { regime: r, url: `https://www.fourchette-et-bikini.fr/regimes/regime-${r}` },
}));

const regimes = $('Code - Régimes').all();
const recettes = new Map();

$input.all().forEach((item, i) => {
  const regime = regimes[i].json.regime;
  const html = item.json.html || '';

  for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/g)) {
    try {
      const data = JSON.parse(m[1]);
      const list = Array.isArray(data) ? data : (data['@graph'] || [data]);
      const il = list.find(x => x['@type'] === 'ItemList');
      if (!il) continue;

      for (const e of il.itemListElement || []) {
        if (!/\/recettes\/.+-\d+\.html$/.test(e.url)) continue; // garde seulement les recettes
        if (recettes.has(e.url)) {
          recettes.get(e.url).regimes.push(regime);
        } else {
          recettes.set(e.url, { url: e.url, nom: e.name, image: e.image, regimes: [regime] });
        }
      }
    } catch (err) {}
  }
});

return [...recettes.values()].map(r => ({ json: r }));

const html = $json.html || '';
const liste = $('Code - Liste recettes').all()[$itemIndex].json;

const toMin = d => {
  const m = (d || '').match(/PT(?:(\d+)H)?(?:(\d+)M)?/);
  return m ? (+(m[1] || 0)) * 60 + (+(m[2] || 0)) : null;
};

for (const b of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/g)) {
  try {
    const data = JSON.parse(b[1]);
    const list = Array.isArray(data) ? data : (data['@graph'] || [data]);
    const r = list.find(x => x['@type'] === 'Recipe');
    if (!r) continue;
    return {
      json: {
        nom: liste.nom,
        url: liste.url,
        regimes: liste.regimes,
        categorie: r.recipeCategory ?? null,
        description: r.description ?? null,
        note: r.aggregateRating ? parseFloat(r.aggregateRating.ratingValue) : null,
        nb_avis: r.aggregateRating?.ratingCount ?? null,
        portions: r.recipeYield ?? null,
        temps_preparation_min: toMin(r.prepTime),
        temps_cuisson_min: toMin(r.cookTime),
        temps_total_min: toMin(r.totalTime),
        calories: r.nutrition?.calories ? parseFloat(r.nutrition.calories) : null,
        ingredients: (r.recipeIngredient || []).map(s => s.replace(/\bnull\s+/g, '').trim()),
        etapes: (r.recipeInstructions || []).map(s => (s.text || s).trim()),
        image: Array.isArray(r.image) ? (r.image[0]?.url || r.image[0]) : (r.image?.url || r.image || liste.image),
      },
    };
  } catch (e) {}
}
return { json: { url: liste.url, erreur: 'Pas de JSON-LD Recipe trouvé' } };

const clean = s => (s || '').replace(' : la meilleure recette', '').trim().toLowerCase();
const cle = j => j.url || clean(j.nom); // identifiant stable : l'URL

// Recettes déjà présentes dans la table (retenues ET rejetées)
const dejaLa = new Set($input.all().map(i => cle(i.json)).filter(Boolean));

// On garde seulement les recettes scrapées absentes de la table
return $('Merge').all().filter(i => !dejaLa.has(cle(i.json)));

// Garde seulement les recettes notées 5 ou plus par l'IA
return $input.all()
  .map((item, index) => ({ json: item.json, pairedItem: index }))
  .filter(i => Number(i.json.output?.note) >= 5);
